// The control tab.
//
// The token lives in localStorage and is pasted in once — the daemon never
// serves it to the page. So a browser that can see the dashboard cannot act on
// it until someone deliberately unlocks this tab.
//
// Paired devices receive their own device token via a 6-digit pairing code
// generated by an authorised session (master or device token). The code is
// displayed as a QR code; the remote browser scans it, receives a token, and
// stores it in localStorage — no master token ever leaves the host.

import { chartEl as h } from './charts.js';
import qrcodegen from './vendor/qrcodegen.js';

const mount = (el, ...kids) =>
  el.replaceChildren(...kids.flat(Infinity).filter((k) => k != null && k !== false));

const TOKEN_KEY = 'fleet-control-token';
let catalogue = null;
let settingsData = null;
let autoscaleData = null;
let lastResult = null;
let busy = null;
let getSnapshot = () => ({ runners: [], repos: [] });

let pairingCode = null;      // { code, url, alternatives, warning, expiresAt } | null
let pairingBusy = false;
let pairingError = null;
let pairingNotice = null;
let pairingTimer = null;
let pairingBaseline = null;  // device keys present when the code was issued
let pairedDevices = [];      // [{ key, name, createdAt, lastSeenAt }]
// Set when the daemon refuses the stored token — it was revoked, rotated, or
// mistyped. Without this the tab says "unlocked" while every action 401s.
let tokenRejected = false;

export function setSnapshotSource(fn) { getSnapshot = fn; }

const storedToken = () => Boolean(localStorage.getItem(TOKEN_KEY));
// "Can this browser act?" — a stored token the daemon has refused does not count.
export const hasToken = () => storedToken() && !tokenRejected;

// For the token-gated GET endpoints — currently the diagnostic bundle — which
// are fetched rather than linked, because an <a href> cannot carry a header.
export const authHeaders = () => {
  const token = localStorage.getItem(TOKEN_KEY);
  return token ? { authorization: `Bearer ${token}` } : {};
};

export async function act(action, args = {}) {
  const token = localStorage.getItem(TOKEN_KEY);
  if (!token) return { ok: false, error: 'this device is locked — pair it or enter the control token in the Control tab' };
  busy = action;
  render();
  try {
    const res = await fetch('/api/action', {
      method: 'POST',
      headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
      body: JSON.stringify({ action, args }),
    });
    const body = await res.json().catch(() => ({ error: `HTTP ${res.status}` }));
    if (isBadToken(res.status, body)) tokenRejected = true;
    lastResult = { action, args, status: res.status, ...body, at: Date.now() };
    return lastResult;
  } catch (err) {
    lastResult = { action, args, ok: false, error: err.message, at: Date.now() };
    return lastResult;
  } finally {
    busy = null;
    await loadCatalogue();
    render();
  }
}

// Confirmation is the UI's job, not the daemon's — but the daemon still refuses
// anything it considers unsafe regardless of what the UI sent.
export async function confirmAct(action, args = {}) {
  const def = catalogue?.actions?.find((a) => a.id === action);
  if (def?.confirm && !window.confirm(`${def.label}\n\n${def.confirm}\n\nProceed?`)) return null;
  return act(action, args);
}

export async function loadCatalogue() {
  const getJson = async (path) => {
    try {
      const res = await fetch(path);
      return res.ok ? await res.json() : null;
    } catch {
      return null;
    }
  };
  [catalogue, settingsData, autoscaleData] = await Promise.all([
    getJson('/api/actions'), getJson('/api/settings'), getJson('/api/autoscale'),
  ]);
  await loadPairedDevices();
}

// -------------------------------------------------------------------------- pairing

// Other 403s are Origin-check refusals, which say nothing about the token.
const isBadToken = (status, body) => status === 403 && body?.error === 'bad token';

// /api/devices doubles as the token check: it is the cheapest authenticated GET.
async function loadPairedDevices() {
  const token = localStorage.getItem(TOKEN_KEY);
  if (!token) { pairedDevices = []; tokenRejected = false; return; }
  try {
    const res = await fetch('/api/devices', { headers: { authorization: `Bearer ${token}` } });
    const body = await res.json().catch(() => ({}));
    if (isBadToken(res.status, body)) {
      tokenRejected = true;
      pairedDevices = [];
      return;
    }
    if (!res.ok) return;
    tokenRejected = false;
    pairedDevices = body.devices ?? [];
  } catch { /* offline — keep what we had */ }
}

function stopPairingTimer() {
  clearInterval(pairingTimer);
  pairingTimer = null;
}

function cancelPairing() {
  stopPairingTimer();
  pairingCode = null;
  render();
}

// While a code is on screen: tick the countdown in place (a full render would
// reset scroll and focus every second), and watch the device list so the
// panel can say "paired" instead of leaving a dead code on screen.
function startPairingTimer() {
  stopPairingTimer();
  let ticks = 0;
  pairingTimer = setInterval(async () => {
    if (!pairingCode) return stopPairingTimer();
    const left = pairingCode.expiresAt - Date.now();
    if (left <= 0) {
      pairingError = 'That pairing code expired. Generate a new one.';
      return cancelPairing();
    }
    const el = document.querySelector('#pair-countdown');
    if (el) el.textContent = `Expires in ${fmtCountdown(left)} · single use`;
    ticks += 1;
    if (ticks % 3 !== 0 || document.hidden) return;
    await loadPairedDevices();
    const added = pairedDevices.find((d) => !pairingBaseline?.has(d.key));
    if (added && pairingCode) {
      pairingNotice = `Paired "${added.name}".`;
      cancelPairing();
    }
  }, 1000);
}

const fmtCountdown = (ms) => {
  const s = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
};

async function startPairing() {
  const token = localStorage.getItem(TOKEN_KEY);
  if (!token) return;
  pairingBusy = true;
  pairingError = null;
  pairingNotice = null;
  render();
  try {
    const res = await fetch('/api/pair/start', {
      method: 'POST',
      headers: { authorization: `Bearer ${token}` },
    });
    const body = await res.json().catch(() => ({}));
    if (res.ok && body.code) {
      pairingCode = { ...body, expiresAt: body.expiresAt ?? Date.now() + 5 * 60 * 1000 };
      pairingBaseline = new Set(pairedDevices.map((d) => d.key));
      startPairingTimer();
    } else {
      if (isBadToken(res.status, body)) tokenRejected = true;
      pairingError = body.error ?? `Could not start pairing (HTTP ${res.status}).`;
    }
  } catch (err) {
    pairingError = `Could not reach the dashboard: ${err.message}`;
  }
  pairingBusy = false;
  render();
}

async function revokeDevice(key, name) {
  const token = localStorage.getItem(TOKEN_KEY);
  if (!token) return;
  if (!window.confirm(`Revoke "${name}"? That device loses control access immediately.`)) return;
  try {
    const res = await fetch('/api/devices/revoke', {
      method: 'POST',
      headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
      body: JSON.stringify({ key }),
    });
    if (!res.ok) {
      const body = await res.json().catch(() => ({}));
      pairingError = `Revoke failed: ${body.error ?? `HTTP ${res.status}`}`;
    }
  } catch (err) {
    pairingError = `Revoke failed: ${err.message}`;
  }
  await loadPairedDevices();
  render();
}

// "iPhone · Safari" reads better in the device list than a raw user agent.
export function friendlyDeviceName(ua = navigator.userAgent) {
  const device =
    /iPad/.test(ua) ? 'iPad'
    : /iPhone/.test(ua) ? 'iPhone'
    : /Android/.test(ua) ? (/Mobile/.test(ua) ? 'Android phone' : 'Android tablet')
    : /Macintosh/.test(ua) ? (navigator.maxTouchPoints > 1 ? 'iPad' : 'Mac')
    : /Windows/.test(ua) ? 'Windows PC'
    : /Linux/.test(ua) ? 'Linux PC'
    : 'Device';
  const browser =
    /Edg\//.test(ua) ? 'Edge'
    : /Firefox\/|FxiOS/.test(ua) ? 'Firefox'
    : /Chrome\/|CriOS/.test(ua) ? 'Chrome'
    : /Safari\//.test(ua) ? 'Safari'
    : '';
  return browser ? `${device} · ${browser}` : device;
}

async function exchangePairCode(code) {
  const suggested = friendlyDeviceName();
  const name = (window.prompt('Name this device (shown in the paired-device list):', suggested) ?? suggested).trim() || suggested;
  try {
    const res = await fetch('/api/pair', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ code, name }),
    });
    const body = await res.json().catch(() => ({ error: `HTTP ${res.status}` }));
    if (body.token) {
      localStorage.setItem(TOKEN_KEY, body.token);
      tokenRejected = false;
      pairingNotice = `This device is paired as "${body.name}". Controls are unlocked.`;
      await loadPairedDevices();
    } else {
      pairingError = `Pairing failed: ${body.error ?? 'unknown error'}`;
    }
  } catch (err) {
    pairingError = `Pairing failed: ${err.message}`;
  }
  render();
  return !pairingError;
}

// Exchange a #pair= fragment code for a device token when the page loads.
export async function maybeExchangePairCode() {
  const m = location.hash.match(/[#&]pair=(\d{6})\b/);
  if (!m) return false;
  // Strip the fragment first so Back or Reload never replays a spent code.
  history.replaceState(history.state, '', location.pathname + location.search);
  pairingError = null;
  const ok = await exchangePairCode(m[1]);
  window.dispatchEvent(new CustomEvent('fleet:paired', { detail: { ok, message: ok ? pairingNotice : pairingError } }));
  return ok;
}

function promptForPairCode() {
  const raw = window.prompt('Enter the 6-digit pairing code shown on an unlocked dashboard (Control → Pair a device):');
  if (raw == null) return;
  const code = raw.replace(/\D/g, '');
  pairingError = null;
  pairingNotice = null;
  if (code.length !== 6) {
    pairingError = 'A pairing code is 6 digits.';
    return render();
  }
  exchangePairCode(code);
}

async function copyText(text) {
  // The async clipboard API only exists in a secure context, and plain LAN
  // http:// is not one. Fall back to a prompt the user can copy from.
  try {
    await navigator.clipboard.writeText(text);
    pairingNotice = 'Link copied.';
    render();
  } catch {
    window.prompt('Copy this link:', text);
  }
}

function qrCodeSvg(text) {
  try {
    const { QrCode } = qrcodegen;
    const qr = QrCode.encodeText(text, QrCode.Ecc.MEDIUM);
    const border = 4;
    const total = qr.size + border * 2;
    const cells = [];
    for (let y = 0; y < qr.size; y++) {
      for (let x = 0; x < qr.size; x++) {
        if (qr.getModule(x, y)) cells.push(`M${x + border},${y + border}h1v1h-1z`);
      }
    }
    const NS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('viewBox', `0 0 ${total} ${total}`);
    svg.setAttribute('class', 'pair-qr');
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', `QR code for ${text}`);
    svg.setAttribute('shape-rendering', 'crispEdges');
    const bg = document.createElementNS(NS, 'rect');
    bg.setAttribute('width', total);
    bg.setAttribute('height', total);
    bg.setAttribute('fill', '#fff');
    const path = document.createElementNS(NS, 'path');
    path.setAttribute('fill', '#000');
    path.setAttribute('d', cells.join(''));
    svg.append(bg, path);
    return svg;
  } catch {
    return null;
  }
}

const relTime = (ms) => {
  if (!ms) return 'never';
  const secs = Math.max(0, Math.round((Date.now() - ms) / 1000));
  if (secs < 60) return 'just now';
  if (secs < 3600) return `${Math.round(secs / 60)}m ago`;
  if (secs < 86400) return `${Math.round(secs / 3600)}h ago`;
  return `${Math.round(secs / 86400)}d ago`;
};

function pairingMessages() {
  return [
    pairingNotice ? h('div', { class: 'pair-notice ok', role: 'status', text: pairingNotice }) : null,
    pairingError ? h('div', { class: 'pair-notice err', role: 'alert', text: pairingError }) : null,
  ];
}

function pairingPanel() {
  if (!hasToken()) return null;

  const codeSection = pairingCode
    ? h('div', { class: 'pair-code-block' },
        pairingCode.warning ? h('div', { class: 'pair-notice warn', text: pairingCode.warning }) : null,
        qrCodeSvg(pairingCode.url),
        h('div', { class: 'pair-code-digits', text: pairingCode.code.replace(/(\d{3})(\d{3})/, '$1 $2') }),
        h('div', { class: 'pair-code-url', text: pairingCode.url.replace(/\/#pair=\d+$/, '') }),
        h('p', {
          class: 'panel-sub',
          id: 'pair-countdown',
          text: `Expires in ${fmtCountdown(pairingCode.expiresAt - Date.now())} · single use`,
        }),
        h('p', {
          class: 'panel-sub',
          text: 'Scan the QR code with the other device, or open the dashboard there and choose "Enter pairing code".',
        }),
        pairingCode.alternatives?.length
          ? h('details', { class: 'pair-alts' },
              h('summary', { text: 'Other addresses for this dashboard' }),
              h('ul', {}, pairingCode.alternatives.map((u) =>
                h('li', {}, h('code', { text: u.replace(/\/#pair=\d+$/, '') })))))
          : null,
        h('div', { class: 'row-actions' },
          h('button', { class: 'btn', text: 'Cancel', onclick: cancelPairing }),
          navigator.share
            ? h('button', {
                class: 'btn', text: 'Share link…',
                onclick: () => navigator.share({ url: pairingCode.url, title: 'Pair with fleet dashboard' }).catch(() => {}),
              })
            : null,
          h('button', { class: 'btn', text: 'Copy link', onclick: () => copyText(pairingCode.url) }),
        ))
    : h('div', { class: 'row-actions' },
        h('button', {
          class: 'btn primary',
          text: pairingBusy ? 'Generating…' : 'Pair a device',
          disabled: pairingBusy ? 'disabled' : null,
          onclick: startPairing,
        }));

  const deviceRows = pairedDevices.map((d) =>
    h('div', { class: 'device-row' },
      h('span', { class: 'device-name', text: d.name }),
      h('span', { class: 'device-meta', text: `paired ${relTime(d.createdAt)} · seen ${relTime(d.lastSeenAt)}` }),
      h('button', { class: 'btn small danger', text: 'Revoke', onclick: () => revokeDevice(d.key, d.name) })));

  return h('div', { class: 'panel', id: 'pairing-panel' },
    h('div', { class: 'panel-head' },
      h('h3', { text: 'Remote devices' }),
      pairedDevices.length ? h('span', { class: 'count', text: String(pairedDevices.length) }) : null),
    h('div', { class: 'panel-sub' },
      'Pair a phone or laptop to use controls remotely. Each device gets its own revocable token; the master token never leaves this machine.'),
    codeSection,
    deviceRows.length
      ? h('div', { class: 'device-list' }, deviceRows)
      : h('p', { class: 'panel-sub', text: 'No devices paired yet.' }));
}

function tokenPanel() {
  const set = storedToken();
  const title = !set ? 'Locked' : tokenRejected ? 'Token no longer accepted' : 'Control unlocked';
  const sub = !set
    ? 'Viewing is open, but actions need this device to be unlocked. The easiest way: on an unlocked dashboard ' +
      '(or with ./fleetctl.sh pair on the runner host) generate a pairing code, then enter it here. ' +
      'You can also paste the master token from ./fleetctl.sh token.'
    : tokenRejected
      ? 'The dashboard refused the token stored in this browser — the device was probably revoked or the token rotated. ' +
        'Forget it and pair again.'
      : 'This browser holds a control token. Actions below will run on the runner host.';
  return h('div', { class: `panel${tokenRejected ? ' panel-warn' : ''}` },
    h('div', { class: 'panel-head' }, h('h3', { text: title })),
    h('div', { class: 'panel-sub', text: sub }),
    pairingMessages(),
    h('div', { class: 'row-actions' },
      set
        ? h('button', {
            class: `btn${tokenRejected ? ' primary' : ''}`, text: 'Forget token',
            onclick: () => {
              localStorage.removeItem(TOKEN_KEY);
              tokenRejected = false;
              pairedDevices = [];
              pairingNotice = null;
              pairingError = null;
              cancelPairing();
            },
          })
        : [
            h('button', { class: 'btn primary', text: 'Enter pairing code', onclick: promptForPairCode }),
            h('button', {
              class: 'btn', text: 'Paste control token',
              onclick: async () => {
                const t = window.prompt('Paste the control token (./fleetctl.sh token)');
                if (!t || !t.trim()) return;
                localStorage.setItem(TOKEN_KEY, t.trim());
                pairingError = null;
                await loadPairedDevices();
                if (tokenRejected) pairingError = 'The dashboard did not accept that token.';
                render();
              },
            }),
          ]));
}

function actionButton(id, { variant = '', argsFn } = {}) {
  const def = catalogue?.actions?.find((a) => a.id === id);
  if (!def) return null;
  const locked = !hasToken();
  const disabled = locked || busy != null;
  return h('button', {
    class: `btn ${variant || (def.danger === 'high' ? 'danger' : def.danger === 'medium' ? 'warn' : '')}`,
    text: busy === id ? `${def.label}…` : def.label,
    disabled: disabled ? 'disabled' : null,
    title: locked ? 'Locked — pair this device or enter the control token above to enable' : (def.confirm ?? def.label),
    onclick: () => confirmAct(id, argsFn ? argsFn() : {}),
  });
}

function fleetPanel() {
  return h('div', { class: 'panel' },
    h('div', { class: 'panel-head' }, h('h3', { text: 'Fleet' })),
    h('div', { class: 'panel-sub' },
      'These run the scripts in ~/actions-runners directly. Preview before applying anything destructive — ' +
        'cleanup and teardown are separate actions from their dry runs on purpose.'),
    h('div', { class: 'row-actions' },
      actionButton('fleet.status'),
      actionButton('fleet.health'),
      actionButton('fleet.healthRepair'),
      actionButton('fleet.preflight'),
      actionButton('fleet.cleanupPreview'),
      actionButton('fleet.cleanupApply')
    )
  );
}

function registerPanel() {
  const snap = getSnapshot();
  const repos = [...new Set([
    ...(snap.repos ?? []).map((r) => r.fullName),
    ...(snap.runners ?? []).map((r) => r.repo),
  ])].sort();

  const repoSel = h('select', { class: 'input', id: 'reg-repo' },
    repos.map((r) => h('option', { value: r, text: r })));
  const labelIn = h('input', { class: 'input', id: 'reg-label', placeholder: 'extra labels (optional, space-separated)' });
  const instSel = h('select', { class: 'input', id: 'reg-instance' },
    [1, 2, 3].map((n) => h('option', { value: String(n), text: n === 1 ? 'first runner' : `instance ${n}` })));

  // Mirror the daemon's own rule back to the operator as they choose, so the
  // constraint is visible before the button rather than only in the error.
  const hint = h('div', { class: 'panel-sub', text: '' });
  const updateHint = () => {
    const repo = repoSel.value;
    const siblings = (snap.runners ?? []).filter((r) => r.repo === repo && r.registered);
    const inst = Number(instSel.value);
    if (inst > 1 && siblings.length) {
      const labels = siblings[0].extraLabels ?? [];
      hint.textContent =
        `The existing runner carries [${labels.join(', ') || 'no extra labels'}]. A second runner must carry ` +
        `the same or it will never match the same runs-on:.`;
    } else if (siblings.length) {
      hint.textContent = `${repo} already has ${siblings.length} runner${siblings.length === 1 ? '' : 's'} on this host.`;
    } else {
      hint.textContent = `${repo} has no runner on this host.`;
    }
  };
  repoSel.addEventListener('change', updateHint);
  instSel.addEventListener('change', updateHint);
  setTimeout(updateHint, 0);

  return h('div', { class: 'panel' },
    h('div', { class: 'panel-head' }, h('h3', { text: 'Register a runner' })),
    h('div', { class: 'panel-sub' },
      'Runs ./register.sh on the host. A second runner only helps a repo whose workflows have more than ' +
        'one job — check the Analytics verdict first.'),
    h('div', { class: 'form-row' }, repoSel, labelIn, instSel,
      actionButton('runner.register', {
        argsFn: () => ({
          repo: repoSel.value,
          label: labelIn.value.trim() || null,
          instance: Number(instSel.value),
        }),
      })
    ),
    hint
  );
}

function settingsPanel() {
  const sd = settingsData;
  if (!sd) return null;

  async function saveSetting(key, value) {
    const token = localStorage.getItem(TOKEN_KEY);
    if (!token) { alert('Enter the control token first.'); return; }
    try {
      const res = await fetch('/api/settings', {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
        body: JSON.stringify({ key, value }),
      });
      const body = await res.json();
      if (!body.ok) throw new Error(body.error ?? `HTTP ${res.status}`);
      await loadCatalogue();
      render();
    } catch (err) {
      alert(`Could not save ${key}: ${err.message}`);
    }
  }

  async function resetSetting(key) {
    const token = localStorage.getItem(TOKEN_KEY);
    if (!token) { alert('Enter the control token first.'); return; }
    try {
      const res = await fetch('/api/settings', {
        method: 'POST',
        headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
        body: JSON.stringify({ key, reset: true }),
      });
      const body = await res.json();
      if (!body.ok) throw new Error(body.error ?? `HTTP ${res.status}`);
      await loadCatalogue();
      render();
    } catch (err) {
      alert(`Could not reset ${key}: ${err.message}`);
    }
  }

  const envOnly = sd.envOnly ?? [];
  const rows = (sd.settings ?? []).filter((s) => !envOnly.includes(s.key));

  return h('div', { class: 'panel' },
    h('div', { class: 'panel-head' },
      h('h3', { text: 'Settings' }),
      h('span', { class: 'count', text: sd.readOnly ? 'read-only mode' : '' })
    ),
    h('div', { class: 'panel-sub' },
      'These take effect immediately — no restart needed. Values set here override the LaunchAgent ' +
        'environment; "reset" removes the override and lets the environment or default apply again.'),
    h('table', { class: 'mini-table settings-table' },
      h('thead', {}, h('tr', {},
        h('th', { text: 'Setting' }), h('th', { text: 'Value' }),
        h('th', { text: 'Source' }), h('th', { text: '' })
      )),
      h('tbody', {}, rows.map((s) => {
        const input = h('input', {
          class: 'input input-sm',
          value: Array.isArray(s.value) ? s.value.join(', ') : String(s.value ?? ''),
          disabled: sd.readOnly || !hasToken() ? 'disabled' : null,
        });
        return h('tr', {},
          h('td', {}, h('span', { text: s.label }), h('div', { class: 'panel-sub', text: s.key })),
          h('td', {}, input),
          h('td', {}, h('span', { class: `flag ${s.source === 'setting' ? 'good' : 'muted'}`, text: s.source })),
          h('td', {},
            !sd.readOnly && hasToken()
              ? h('div', { class: 'row-actions' },
                  h('button', {
                    class: 'btn tiny', text: 'Set',
                    onclick: () => saveSetting(s.key, input.value),
                  }),
                  s.source !== 'default'
                    ? h('button', {
                        class: 'btn tiny', text: 'Reset',
                        onclick: () => resetSetting(s.key),
                      })
                    : null
                )
              : null
          )
        );
      }))
    )
  );
}

function autoscalePanel() {
  const snap = getSnapshot();
  const cap = autoscaleData?.capacity ?? snap.capacity ?? {};
  const sizing = autoscaleData?.sizing ?? snap.sizing ?? [];
  const decisions = autoscaleData?.decisions ?? [];

  return h('div', { class: 'panel' },
    h('div', { class: 'panel-head' },
      h('h3', { text: 'Autoscaling readiness' }),
      h('span', { class: `flag ${cap.ok ? 'good' : 'warning'}`, text: cap.ok ? 'headroom available' : 'no headroom' })
    ),
    h('div', { class: 'panel-sub' },
      cap.ok
        ? `Host can accept more runners: ${cap.busy ?? 0} busy, ${cap.ceiling ?? 0} ceiling.`
        : `Scale-up blocked: ${(cap.reasons ?? []).join('; ') || 'unknown reason'}`
    ),
    sizing.length
      ? [
          h('h4', { text: 'Per-repo sizing (from job history)' }),
          h('table', { class: 'mini-table' },
            h('thead', {}, h('tr', {},
              h('th', { text: 'Repo' }), h('th', { class: 'num', text: 'Have' }),
              h('th', { class: 'num', text: 'Want' }), h('th', { text: 'Reason' })
            )),
            h('tbody', {}, sizing.map((s) =>
              h('tr', {},
                h('td', { class: 'mono', text: s.repo.split('/').pop() }),
                h('td', { class: 'num', text: String(s.have) }),
                h('td', { class: `num ${s.delta > 0 ? 'serious' : 'good'}`, text: String(s.want) }),
                h('td', { text: s.reason })
              )
            ))
          ),
        ]
      : null,
    decisions.length
      ? [
          h('h4', { text: 'Recent dry-run decisions' }),
          h('table', { class: 'mini-table' },
            h('thead', {}, h('tr', {},
              h('th', { text: 'When' }), h('th', { text: 'Repo' }),
              h('th', { text: 'Decision' }), h('th', { text: 'Reason' })
            )),
            h('tbody', {}, decisions.slice(0, 10).map((d) =>
              h('tr', {},
                h('td', { text: new Date(d.ts).toLocaleString() }),
                h('td', { class: 'mono', text: d.repo.split('/').pop() }),
                h('td', {}, h('span', { class: `flag ${d.action === 'proposed' ? 'good' : 'muted'}`, text: d.action })),
                h('td', { text: d.reason })
              )
            ))
          ),
        ]
      : h('div', { class: 'empty', text: 'No autoscaling decisions recorded yet. They appear when a run has been queued longer than the threshold.' })
  );
}

function resultPanel() {
  if (!lastResult) return null;
  const r = lastResult;
  return h('div', { class: 'panel' },
    h('div', { class: 'panel-head' },
      h('h3', { text: r.ok ? 'Result' : 'Failed' }),
      h('span', { class: `flag ${r.ok ? '' : 'serious'}`, text: r.ok ? `exit ${r.code ?? 0}` : `HTTP ${r.status ?? '–'}` })
    ),
    h('div', { class: 'panel-sub', text: r.command ?? r.action }),
    h('pre', { class: 'diag', text: r.output || r.error || '(no output)' })
  );
}

function logPanel() {
  const rows = catalogue?.recent ?? [];
  if (!rows.length) return null;
  return h('div', { class: 'panel' },
    h('div', { class: 'panel-head' }, h('h3', { text: 'Recent actions' })),
    h('div', { class: 'panel-sub', text: 'Every action this daemon has run, successful or not.' }),
    h('table', { class: 'mini-table' },
      h('thead', {}, h('tr', {},
        h('th', { text: 'When' }), h('th', { text: 'Action' }),
        h('th', { text: 'Command' }), h('th', { class: 'num', text: 'Exit' })
      )),
      h('tbody', {}, rows.map((x) =>
        h('tr', {},
          h('td', { text: new Date(x.ts).toLocaleString() }),
          h('td', { class: 'mono', text: x.action }),
          h('td', { class: 'mono', text: (x.command ?? '–').slice(0, 70) }),
          h('td', { class: `num ${x.ok ? '' : 'fail'}`, text: x.ok ? '0' : String(x.exit_code ?? 'err') })
        )
      ))
    )
  );
}

export function render() {
  const root = document.querySelector('#view-control');
  if (!root) return;
  if (catalogue?.readOnly) {
    return mount(root,
      h('div', { class: 'section-head' }, h('h2', { text: 'Control' })),
      h('div', { class: 'empty', text: 'This daemon is running read-only (FLEET_READ_ONLY=1). No actions are available.' })
    );
  }
  mount(root,
    h('div', { class: 'section-head' },
      h('h2', { text: 'Control' }),
      h('span', { class: 'count', text: hasToken() ? 'unlocked' : tokenRejected ? 'token refused' : 'locked' })
    ),
    tokenPanel(),
    pairingPanel(),
    autoscalePanel(),
    settingsPanel(),
    fleetPanel(),
    registerPanel(),
    resultPanel(),
    logPanel()
  );
}
